// Makes *target point at the largest of values[0 .. count-1], or nullptr when count is 0.
void aimAtLargest(int* values, int count, int** target)
{
    *target = nullptr;
    for (int i{ 0 }; i < count; ++i)
    {
        if (*target == nullptr || values[i] > **target)
            *target = &values[i];
    }
}

unitTests:
TEST("points at the largest") { int s[]{ 4, 9, 2 }; int* best{ nullptr }; aimAtLargest(s, 3, &best); CHECK(best == &s[1]); }
TEST("the first of equal values") { int s[]{ 4, 9, 2, 9 }; int* best{ nullptr }; aimAtLargest(s, 4, &best); CHECK(best == &s[1]); }
TEST("negative numbers") { int s[]{ -7, -3, -10 }; int* best{ nullptr }; aimAtLargest(s, 3, &best); CHECK(best == &s[1]); }
TEST("nothing to aim at") { int s[]{ 1 }; int* best{ s }; aimAtLargest(s, 0, &best); CHECK(best == nullptr); }
TEST("writing through the result changes the array") { int s[]{ 1, 5, 3 }; int* best{ nullptr }; aimAtLargest(s, 3, &best); *best = 0; CHECK_EQ(s[1], 0); }

